(() => {
'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const app=$('#app'), overlay=$('#overlay-root');
const state={work:false,policy:false,breakfast:false,cancel:false,corporate:false,wifi:false,sort:'recommended',hotel:null,view:'search',favorites:new Set(),city:'Москва',guests:1,checkin:'2026-03-09',checkout:'2026-03-12'};
const popularFilters=[['Корпоративный тариф','corporate'],['Включён завтрак','breakfast'],['Бесплатная отмена','cancel'],['В тревел-политике','policy'],['Wi-Fi','wifi']];
const leisureFilters=[['Кондиционер','aircon'],['Квартиры','apartments'],['Стиральная машина','washer'],['Вид на море','sea'],['Бассейн','pool']];
const activePopularFilters=()=>state.work?popularFilters:leisureFilters;
const quickFilters=()=>state.work?[popularFilters.find(([,key])=>key==='policy'),...popularFilters.filter(([,key])=>key!=='policy')]:leisureFilters;
const hotels=[{id:'azimut',name:'AZIMUT Смоленская 4*',price:34600,policy:false,breakfast:true,cancel:true,image:'hotel-figma.png',rating:'4.9',distance:'7.9'},{id:'garden',name:'AZIMUT Смоленская 3*',price:29600,policy:true,breakfast:true,cancel:true,image:'hotel-2b-figma.png',rating:'4.9',distance:'7.9'},{id:'arbat',name:'Отель Арбат 4*',price:23800,policy:true,breakfast:true,cancel:true,image:'apartment-03.png',rating:'4.8',distance:'2.1'},{id:'panorama',name:'Панорама Москва 4*',price:32400,policy:false,breakfast:false,cancel:true,image:'apartment-04.png',rating:'4.7',distance:'4.2'},{id:'center',name:'Городской отель 3*',price:21900,policy:true,breakfast:true,cancel:false,image:'apartment-05.png',rating:'4.8',distance:'3.6'}];
function element(html){const t=document.createElement('template');t.innerHTML=html.trim();return t.content.firstElementChild;}
function button(label,action,theme='secondary',extra=''){let b=element(UIKIT[theme==='dark'?'dark':theme==='primary'?'button':'secondary']).querySelector('button');b.querySelector('.button__label').innerHTML=label;b.removeAttribute('name');b.dataset.action=action;b.className+=' '+extra;return b.outerHTML;}
function icon(file,size=24){return `<img src="assets/${file}" width="${size}" height="${size}" alt="">`;}
function iconButton(file,label,action,size=24){let b=element(button('',action));b.setAttribute('aria-label',label);b.classList.add('button--shape-square');b.querySelector('.button__content').innerHTML=icon(file,size);return b.outerHTML;}
function input(label,value,id,type='text'){let n=element(UIKIT.input);n.querySelector('label').textContent=label;n.querySelector('label').htmlFor=id;const c=n.querySelector('input');c.id=id;c.value=value;c.setAttribute('value',value);c.type=type;if(type==='date'){c.type='text';c.readOnly=true;c.dataset.action='dates';c.value=new Date(value+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'});c.setAttribute('value',c.value);}c.setAttribute('aria-label',label);c.removeAttribute('label');return n.outerHTML;}
function check(label,key,checked=false){let n=element(UIKIT.checkbox).querySelector('label');let i=n.querySelector('input');i.setAttribute('aria-label',label);i.dataset.filter=key;if(checked)i.setAttribute('checked','');n.querySelector('.checkbox__auto-010').textContent=label;return `<div class="filter-item">${n.outerHTML}</div>`;}
function toggle(){let n=element(UIKIT.switch).children[1].cloneNode(true);n.classList.replace('switch--size-xl',matchMedia('(max-width:768px)').matches?'switch--size-l':'switch--size-m');n.classList.toggle('switch--checked',state.work);n.classList.toggle('switch--checked-contrast',state.work);n.dataset.checked=String(state.work);n.dataset.action='work';n.setAttribute('role','switch');n.setAttribute('tabindex','0');n.setAttribute('aria-checked',String(state.work));n.setAttribute('aria-label','Еду по работе');return n.outerHTML;}
function workLine(){return `<div class="work-line"><span class="work-title">Еду по работе</span><button class="more" data-action="work-info" aria-label="О режиме поездки по работе">${icon('2d881.svg',12)}</button>${toggle()}</div>`;}
function badge(text,positive=false){const n=element(positive?UIKIT.positive:UIKIT.negative).firstElementChild.children[0].cloneNode(true);n.querySelector('span').textContent=text;return n.outerHTML;}
function rating(text){const n=element(UIKIT.rating);n.setAttribute('aria-label','Оценка '+text);n.querySelector('span').textContent=text;return n.outerHTML;}
hotels.forEach((h,i)=>{h.corporate=[1,2,4].includes(i);h.wifi=true;});
function quickFilter(title,key){const b=element(button(title,'quick-'+key,state[key]?'dark':'secondary'));b.setAttribute('aria-pressed',String(state[key]));return b.outerHTML;}
const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
function filtered(){let list=hotels.filter(h=>(!state.policy||h.policy)&&(!state.breakfast||h.breakfast)&&(!state.cancel||h.cancel)&&(!state.corporate||h.corporate)&&(!state.wifi||h.wifi));if(state.sort==='cheap')list.sort((a,b)=>a.price-b.price);if(state.sort==='expensive')list.sort((a,b)=>b.price-a.price);if(state.sort==='rating')list.sort((a,b)=>Number(b.rating)-Number(a.rating));return list;}
function card(h){let n=element(UIKIT.card);n.classList.add('product-card');n.dataset.hotel=h.id;n.dataset.action='hotel';n.dataset.id=h.id;n.setAttribute('role','link');n.setAttribute('tabindex','0');n.setAttribute('aria-label','Открыть '+h.name);const b=n.querySelector('.card__body');b.innerHTML=`<div class="hotel-inner"><div class="hotel-photo" data-action="hotel" data-id="${h.id}"><img src="assets/${h.image}" alt="Номер в ${h.name}"><span class="hotel-recommend">${matchMedia('(max-width:768px)').matches?UIKIT.recommend:UIKIT.recommendIcon}</span><button class="hotel-favorite" data-action="favorite" data-id="${h.id}" aria-label="Добавить в избранное" aria-pressed="${state.favorites.has(h.id)}">${icon('0308c.svg')}</button></div><div class="hotel-content"><div><div class="hotel-top"><div class="hotel-heading"><h2 class="hotel-name" data-action="hotel" data-id="${h.id}">${h.name}</h2><p class="hotel-meta">Отель · ${state.city} · ${h.distance} км до центра</p></div><div class="hotel-rating"><span class="rating">${rating(h.rating)}</span><span class="review-count">421 отзыв</span></div></div>${state.work&&!h.policy?`<div class="policy-badge" data-action="policy-info">${badge('Не в тревел-политике')}</div>`:state.policy?`<div class="benefits">${h.cancel?badge('Бесплатная отмена',true):''}${h.breakfast?badge('Завтрак включён',true):''}</div>`:''}</div><div class="hotel-bottom"><div><div class="price-line"><div class="price">${money(h.price)}</div>${h.id==='azimut'?UIKIT.discount+'<s class="old-price">40 000 ₽</s>':''}</div><p class="hotel-caption">3 ночи${h.id==='azimut'?' · Кровать в общем номере':''}</p></div>${button('Выбрать','hotel','primary','choose').replace('data-action="hotel"',`data-action="hotel" data-id="${h.id}"`)}</div></div></div>`;return n.outerHTML;}
function searchbar(){return `<div class="searchbar"><div class="search-fields"><div class="search-field">${input('Куда',state.city,'destination')}</div><div class="search-field">${input('Заезд',state.checkin,'checkin','date')}</div><div class="search-field">${input('Выезд',state.checkout,'checkout','date')}</div><div class="search-field">${button(state.guests+' взрослый','guests')}</div></div>${button('Найти','search','primary','search-button')}</div>`;}
function map(){return `<aside class="map" aria-label="Отели на карте"><img class="map-bg" src="assets/map-figma.png" alt="Карта Москвы"><div class="map-pins">${filtered().map((h,i)=>`<div class="map-pin" style="left:${[52,28,68,42,70][i]}%;top:${[26,42,57,72,82][i]}%">${button(money(h.price),'hotel').replace('data-action="hotel"',`data-action="hotel" data-id="${h.id}"`)}</div>`).join('')}</div><div class="map-controls">${button('+','zoom-in')}${button('−','zoom-out')}</div></aside>`;}
function filters(){return `<div class="filter-group"><h3>Популярное</h3>${activePopularFilters().map(([title,key])=>check(title,key,state[key])).join('')}</div><div class="filter-group"><h3>Цена за 3 ночи</h3><div class="price-fields">${input('От, ₽','0','price-min','number')}${input('До, ₽','900000','price-max','number')}</div></div><div class="filter-group"><h3>Тип размещения</h3>${check('Отель','hotel-type')}${check('Апартаменты','apartment-type')}${check('Санаторий','sanatorium')}${check('Дом отдыха','rest')}${check('Хостел','hostel')}</div><div class="filter-group"><h3>Звёздность</h3>${check('5★','five-stars')}${check('4★','four-stars')}${check('3★','three-stars')}</div>`;}
function results(){app.innerHTML=`<div class="layout"><section class="search-area">${searchbar()}<h1>Отели и гостиницы Москвы</h1></section><div class="mobile-top"><span class="mobile-back">${iconButton('e5281.svg','Изменить поиск','back-search')}</span><div class="mobile-search">${button(`${state.city}<span class="search-summary-sub">${icon('cb7f5.svg',12)}9–12 марта&nbsp; ${icon('0f858.svg',12)}${state.guests}</span>`,'back-search')}</div></div><nav class="mobile-chips" aria-label="Фильтры">${iconButton('8eb0c.svg','Все фильтры','filters',16)}${iconButton('31c3a.svg','Сортировка','sort',16)}${button('Цена','price')}${quickFilters().map(([title,key])=>quickFilter(title,key)).join('')}</nav><div class="mobile-work">${workLine()}</div><aside class="sidebar">${workLine()}${filters()}<div class="filter-group">${button('Сбросить','reset')}</div></aside><section class="results" aria-label="Результаты поиска"><div class="results-top"><span class="results-count">Найдено объектов: ${state.policy||state.breakfast||state.cancel?filtered().length:765}</span>${button({recommended:'Рекомендуемая',cheap:'Сначала дешевле',expensive:'Сначала дороже',rating:'Высокий рейтинг'}[state.sort],'sort')}</div>${filtered().map(card).join('')||'<div class="empty">Нет подходящих отелей. Попробуйте изменить фильтры.</div>'}</section>${map()}<div class="mobile-map">${button('Карта','map','dark')}</div></div>`;syncPolicy();}
function search(){const reset=element(button('Сбросить','noop'));reset.removeAttribute('data-action');reset.setAttribute('tabindex','-1');reset.setAttribute('inert','');reset.classList.replace('button--secondary','ui__auto-505');app.innerHTML=`<section class="search-page"><div class="search-page-inner"><div class="header-tabs">${button('Отели','noop','primary')}${button('Авиабилеты','noop')}${button('Ж/д билеты','noop')}</div><h1>Куда поедем?</h1>${searchbar()}<div class="search-mobile-form figma-start" data-figma-node="12641:233629"><div class="start-status" aria-hidden="true"><span>9:41</span>${icon('af6c7.svg',67)}</div><span class="start-close" aria-hidden="true">${icon('e28ce.svg')}</span><div class="search-service-tabs" aria-label="Отели"><div class="start-tab start-tab-current"><span>Отели</span><div>${icon('b9dde.svg')}</div></div><div class="start-tab"><span>Авиа</span><div>${icon('ba33b.svg')}</div></div><div class="start-tab"><span>Ж/д</span><div>${icon('b1402.svg')}</div></div></div><div class="start-fields"><div class="search-group start-destination"><h2>Куда поедем?</h2><div class="start-city">Москва</div></div><div class="search-group search-line"><span>Когда</span><strong>9 марта</strong></div><div class="search-group search-line"><span>Кто</span><strong>1 взрослый</strong></div></div><div class="search-footer">${reset.outerHTML}${button('Найти','search','primary')}</div><div class="start-home-indicator" aria-hidden="true"></div></div></div></section>`;}
function details(){const h=hotels.find(h=>h.id===state.hotel)||hotels[0];app.innerHTML=`<div class="detail-layout"><span class="back-button">${button('← К результатам поиска','back-results')}</span><h1>${h.name}</h1><div class="detail-photos"><img src="assets/${h.image}" alt="Номер в отеле"><img src="assets/hotel-figma.png" alt="Интерьер отеля"></div><div class="detail-island"><h2>Об отеле</h2><p>${state.city} · ${h.distance} км до центра · ${h.rating} — 421 отзыв</p>${state.work&&!h.policy?`<div class="policy-badge">${badge('Не в тревел-политике')}</div>`:''}</div><div class="detail-island"><h2>Выберите номер</h2><div class="offer-row"><div><h3>Стандартный номер</h3><p>9–12 марта · 3 ночи · ${state.guests} взрослый</p><p>${h.breakfast?'Завтрак включён':'Без завтрака'} · ${h.cancel?'Бесплатная отмена':'Без отмены'}</p></div><div><div class="price">${money(h.price)}</div>${button('Выбрать номер','select-room','primary')}</div></div></div></div>`;}
function completion(){overlay.innerHTML='';document.body.classList.remove('overlay-open');app.innerHTML='<section class="completion-page" role="status" aria-label="Номер выбран"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 12l4 4L19 6" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg></section>';}
function render(){document.body.dataset.prototypeView=state.view;if(state.view==='selected'){completion();return;}const frame=document.getElementById('native-desktop');if(matchMedia('(min-width:769px)').matches&&state.view!=='hotel'&&frame){const next=state.view==='search'?'desktop-start.html':'desktop.html'+(state.policy?'#policy':state.work?'#work':'');if(!frame.getAttribute('src')||frame.getAttribute('src').split('#')[0]!==next.split('#')[0])frame.src=next;}if(state.view==='search')search();else if(state.view==='hotel')details();else results();}
function navigate(path){history.pushState({},'','#'+path);readPath();window.scrollTo(0,0);render();}
function readPath(){const p=location.hash.startsWith('#/')?location.hash.slice(1):'/';state.view=p.includes('/selected/')?'selected':p.includes('/hotel/')?'hotel':p.includes('/results')?'results':'search';if(state.view==='hotel'||state.view==='selected')state.hotel=p.split(/\/(?:hotel|selected)\//)[1].split('/')[0];state.work=p.includes('/work/')||p.includes('/policy/');state.policy=p.includes('/policy/');}
function updateResultsPath(){const p=state.policy?'/policy/results':state.work?'/work/results':'/results';history.replaceState({},'','#'+p);}
let restoreFocus=null;
function close(){overlay.innerHTML='';document.body.classList.remove('overlay-open');restoreFocus?.focus?.();}
function modal(title,content,actions=''){restoreFocus=document.activeElement;overlay.innerHTML=`<div class="overlay"><section role="dialog" aria-modal="true" aria-label="${title}" class="dialog"><div class="dialog-header"><h2>${title}</h2>${button('Закрыть','close')}</div>${content}${actions?`<div class="dialog-actions">${actions}</div>`:''}</section></div>`;document.body.classList.add('overlay-open');$('button',overlay)?.focus();}
function syncPolicy(){$$('[data-action="policy"]').forEach(b=>{b.setAttribute('aria-pressed',String(state.policy));b.classList.toggle('ui__auto-441',state.policy);b.classList.remove('button--primary');b.classList.toggle('button--secondary',!state.policy);});}
function log(name,data={}){let events=[];try{events=JSON.parse(sessionStorage.getItem('work-trip-events')||'[]');events.push({event:name,time:Date.now(),path:location.hash.slice(1)||'/',...data});sessionStorage.setItem('work-trip-events',JSON.stringify(events));}catch{}window.dispatchEvent(new CustomEvent('prototype-event',{detail:{name,...data}}));}
document.addEventListener('click',e=>{
 const a=e.target.closest('[data-action]');if(!a)return;const action=a.dataset.action;const id=a.dataset.id;log(action,{id});
 if(action==='close'){close();return;}
 if(action==='search'){state.city=(matchMedia('(max-width:768px)').matches?$('#mobile-destination')?.value:$('#destination')?.value)||state.city;navigate('/results');}
 if(action==='back-search'){navigate('/');}
 if(action==='back-results'){navigate(state.policy?'/policy/results':state.work?'/work/results':'/results');}
 if(action==='work'){state.work=!state.work;[...popularFilters,...leisureFilters].forEach(([,key])=>{state[key]=false;});updateResultsPath();results();}
 if(action==='policy'){state.policy=!state.policy;if(state.policy)state.work=true;updateResultsPath();results();}
 if(action.startsWith('quick-')){const key=action.slice(6);state[key]=!state[key];if(key==='policy'&&state.policy)state.work=true;updateResultsPath();results();}
 if(action==='cancel'){state.cancel=!state.cancel;results();}
 if(action==='favorite'){e.stopPropagation();state.favorites.has(id)?state.favorites.delete(id):state.favorites.add(id);results();}
 if(action==='hotel'){state.hotel=id;navigate(`/${state.policy?'policy/':state.work?'work/':''}hotel/${id}`);close();}
 if(action==='work-info'){modal('Еду по работе','<p>В этом режиме видны корпоративные тарифы и соответствие отелей правилам вашей компании.</p>');}
 if(action==='policy-info'){modal('Не в тревел-политике','<p>Предложение не соответствует правилам компании. Вы можете посмотреть другие варианты или выбрать его, если компания согласует исключение.</p>');}
 if(action==='filters'){modal('Фильтры',filters(),button('Показать отели','apply-filters','primary')+button('Сбросить','reset'));}
 if(action==='apply-filters'){close();updateResultsPath();results();}
 if(action==='reset'){[...popularFilters,...leisureFilters].forEach(([,key])=>{state[key]=false;});updateResultsPath();close();results();}
 if(action==='sort'){modal('Сортировка',`<div class="sort-options">${[['recommended','Рекомендуемая'],['cheap','Сначала дешевле'],['expensive','Сначала дороже'],['rating','Высокий рейтинг']].map(([v,t])=>button(t,'sort-'+v,state.sort===v?'primary':'secondary')).join('')}</div>`);}
 if(action.startsWith('sort-')){state.sort=action.slice(5);close();results();}
 if(action==='price'){modal('Цена за 3 ночи',`<div class="price-fields">${input('От, ₽','0','min-price','number')}${input('До, ₽','100000','max-price','number')}</div>`,button('Показать отели','apply-price','primary'));}
 if(action==='apply-price'){let lo=Number($('#min-price').value),hi=Number($('#max-price').value);close();results();$$('.product-card').forEach(c=>{const h=hotels.find(h=>h.id===c.dataset.hotel);c.hidden=h.price<lo||h.price>hi;});}
 if(action==='guests'){modal('Кто поедет?',`<div class="search-line"><span>Взрослые</span>${button('−','guest-minus')}<strong id="guest-count">${state.guests}</strong>${button('+','guest-plus')}</div>`,button('Готово','apply-guests','primary'));}
 if(action==='guest-minus'||action==='guest-plus'){state.guests=Math.max(1,Math.min(6,state.guests+(action==='guest-plus'?1:-1)));$('#guest-count').textContent=state.guests;}
 if(action==='apply-guests'){close();render();}
 if(action==='dates'){modal('Даты поездки',input('Заезд',state.checkin,'date-from','date')+input('Выезд',state.checkout,'date-to','date'),button('Готово','apply-dates','primary'));}
 if(action==='apply-dates'){close();render();}
 if(action==='clear-search'){state.city='';search();}
 if(action==='map'){modal('Карта',map());$('.dialog').classList.add('map-dialog');}
 if(action==='zoom-in'||action==='zoom-out'){const m=a.closest('.map');const img=$('.map-bg',m);let z=Number(img.dataset.zoom||1)+(action==='zoom-in'?.15:-.15);z=Math.max(.8,Math.min(2,z));img.dataset.zoom=z;img.style.transform=`scale(${z})`;}
 if(action==='select-room'){log('selected',{hotel:state.hotel,work:state.work,policy:state.policy});close();navigate(`/${state.policy?'policy/':state.work?'work/':''}selected/${state.hotel}`);}
});
document.addEventListener('change',e=>{const k=e.target.dataset.filter;if(k){if(activePopularFilters().some(([,key])=>key===k)){state[k]=e.target.checked;if(k==='policy'&&state.policy)state.work=true;log('filter',{key:k,value:e.target.checked});if(!overlay.innerHTML){updateResultsPath();results();}}}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.product-card[role=link]')){e.preventDefault();e.target.click();}if(e.key==='Escape')close();if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role=switch]')){e.preventDefault();e.target.click();}if(e.key==='Tab'&&overlay.innerHTML){const f=$$('button,input,[tabindex="0"]',overlay).filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0]?.focus();}}});
overlay.addEventListener('click',e=>{if(e.target.classList.contains('overlay'))close();});
document.addEventListener('click',e=>{const a=e.target.closest('#desktop-header a');if(a)e.preventDefault();});
window.addEventListener('popstate',()=>{close();readPath();render();});
window.addEventListener('hashchange',()=>{close();readPath();render();});
matchMedia('(max-width:768px)').addEventListener('change',render);
fetch('header.html').then(r=>r.text()).then(t=>{$('#desktop-header').innerHTML=t;$$('#desktop-header img').forEach(i=>i.loading='eager');});
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.data?.type==='trip-state'){readPath();render();}});
readPath();render();
})();
